def build():
 d=Document(); sec=d.sections[0]; sec.page_height=Cm(29.7);sec.page_width=Cm(21);sec.top_margin=Cm(1.8);sec.bottom_margin=Cm(1.8);sec.left_margin=Cm(2);sec.right_margin=Cm(2)
 for name in ['Normal','Title','Heading 1','Heading 2']:
  st=d.styles[name];st.font.name='Arial';st.font.color.rgb=RGBColor(0,0,0)
 d.styles['Normal'].font.size=Pt(10.5);d.styles['Normal'].paragraph_format.space_after=Pt(5);d.styles['Normal'].paragraph_format.line_spacing=1.1
 d.styles['Title'].font.size=Pt(22);d.styles['Heading 1'].font.size=Pt(15);d.styles['Heading 2'].font.size=Pt(12)
 labels={'PASS':'Пройден','PARTIAL':'Частично','FAIL':'Не пройден','EXCLUDED':'Исключён','RUNNING':'Не завершён'}
 colors={'PASS':'188038','PARTIAL':'B88600','FAIL':'C5221F','EXCLUDED':'666666','RUNNING':'666666'}
 def p(text):return d.add_paragraph(text)
 def result(s):
  q=d.add_paragraph();r=q.add_run(labels.get(s,s));r.bold=True;r.font.color.rgb=RGBColor.from_string(colors.get(s,'000000'))
 d.add_paragraph('Протокол проверки системы поддержки исследования',style='Title')
 p('12 ноября 2026 года • ПМИ версия 2 • локальный испытательный стенд')
